"""Layer 15 MLP down_proj, component 3203: a weak, mostly unexplained contributor.

What it does: its activation is the component's read-out of the MLP hidden state,
(hidden . V_c) * |U_c|. Across the model's text it is close to zero-mean noise (std about
0.29) spread over thousands of hidden units, with no single unit or direction carrying
it. The few simple word classes that shift it are used here:

* chat / agent / reasoning markup ("assistant", "<think>", "</think>", "arguments",
  tool-call tags) pushes it clearly negative;
* contrast and concession words ("however", "although", "though", "nor", "too") and a
  few emphatic words push it mildly positive;
* whitespace-only tokens push it slightly negative;
* every other token sits at the overall mean, about -0.03.

Those rules explain well under 1% of its variance. A per-token lookup table would reach
about 3%, but it has no concept behind it, so it is not used here.
"""

MARKUP = {
    "assistant", "user", "system", "arguments", "<think>", "</think>",
    "<tool_call>", "</tool_call>", "<|im_start|>", "<|im_end|>",
}
CONTRAST = {"however", "although", "though", "but", "nor", "too", "Wait", "particularly", "especially"}
MEAN = -0.03
MARKUP_VALUE = -0.13
CONTRAST_VALUE = 0.08
SPACE_VALUE = -0.06

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if word in MARKUP:
        value = MARKUP_VALUE
    elif word in CONTRAST:
        value = CONTRAST_VALUE
    elif token and not word:
        value = SPACE_VALUE
    else:
        value = MEAN
    return carry, float(value)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:3206 (layer 15 MLP down-projection).

What it does: it is a "coordinator" detector. It fires on words that join two parallel
units -- "and", "or", "but", "nor", their translations, and commas -- and it fires most
when the word just before them is a verb or a preposition, that is, when the thing being
joined is a predicate or a verb phrase ("find [and] read", "order [and] direct",
"will [,] and", "subject to [,] and"). It is weak after nouns and symbols, where the
joined units are noun items in a list ("rate, ratio, [,] and proportion", "A and B").
Adverbs, pronouns and adjectives sit in between.

The program looks only at the previous word and the current token; it has no state.
"""

import regex
from wordnet import parts_of_speech

READS = ()

# Coordinating words, in English and a few other languages.
CONJUNCTIONS = {"and", "or", "nor", "but", "und", "et", "y", "ou", "oder", "или", "и", "或", "和", "、", "与", "并", "&", "/or"}
MODALS = {"can", "may", "will", "would", "should", "must", "could", "might", "shall"}
PREPOSITIONS = {"to", "for", "on", "in", "by", "with", "of", "at", "from", "into", "about", "than", "as", "up", "out", "back", "down", "off", "over", "through", "under", "before", "after", "during"}
PRONOUNS = {"it", "them", "him", "her", "me", "us", "you", "they", "we", "he", "she", "i", "this", "that", "there"}

# Typical activation after each kind of previous word (fit on training text).
CONJ_VALUE = {"verb": 10.0, "prep": 10.0, "adverb": 5.0, "pronoun": 3.0, "adjective": 3.0, "other": 1.0}
COMMA_VALUE = {"verb": 5.0, "prep": 5.0, "pronoun": 3.0, "adjective": 1.0, "adverb": 1.0, "other": 1.0, "noun": 0.0, "symbol": 0.0}


def word_kind(token):
    """Sort a word into a rough part-of-speech kind; symbols, digits and brackets are 'symbol'."""
    w = token.strip().lower()
    if w in MODALS:
        return "verb"
    if w in PREPOSITIONS:
        return "prep"
    if w in PRONOUNS:
        return "pronoun"
    if not regex.fullmatch(r"\p{L}+", w):
        return "symbol"
    pos = parts_of_speech(w)
    if "verb" in pos and "noun" not in pos:
        return "verb"
    if "adverb" in pos:
        return "adverb"
    if "adjective" in pos:
        return "adjective"
    if "noun" in pos:
        return "noun"
    return "other"


def step(carry, prefix, upstream):
    """Activation at the newest token: a coordinator or comma, scaled by the word before it."""
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0  # first token of a document: nothing before it
    before = word_kind(prefix.token_strings[-2])
    if token.strip().lower() in CONJUNCTIONS:
        return None, CONJ_VALUE.get(before, 1.0)
    if token == ",":
        return None, COMMA_VALUE.get(before, 0.0)
    return None, 0.0

"""Layer 15, MLP hidden unit 3223 (component 3223 of layers.15.mlp.down_proj).

This component reads almost only MLP hidden unit 3223 of layer 15, so its activation is that
unit's value. The unit is a "person as object" detector: it is strongly positive on an object
pronoun (me, him, her, us, them, you) that is the object of a verb of talking, asking, inviting
or contacting ("told me", "asked them", "with you"), and on the word right after such a
pronoun when that word is a preposition or "to" ("him in", "me to", "you with").
It is near zero, or slightly negative, when the pronoun follows a causing or permitting word
("let me", "allow us", "for them", "between them"), and close to zero everywhere else.

The rule is coarse: it captures only part of the variance, since the unit's largest values
depend on context that a word list does not describe.
"""

READS = ()

OBJECT_PRONOUNS = {"me", "him", "her", "us", "them", "you"}
TALK_VERBS = {
    "tell", "told", "telling", "ask", "asked", "asking", "asks", "invite", "invited",
    "contact", "email", "send", "sent", "call", "called", "thank", "join", "love", "see",
    "saw", "with", "meet", "met", "message", "write", "wrote", "teach", "taught", "warn",
    "show", "showed", "help", "helped", "want", "wanted", "bring", "take", "took", "follow",
}
CAUSE_WORDS = {
    "let", "lets", "letting", "make", "makes", "making", "made", "allow", "allows",
    "allowing", "allowed", "for", "between", "before", "after", "against", "about", "upon", "of",
}
PARTICLES = {
    "to", "in", "for", "on", "with", "as", "at", "into", "up", "down", "out", "over",
    "through", "by", "about",
}


def step(carry, prefix, upstream):
    i = prefix.position
    cur = prefix.token_strings[i].strip().lower()
    prev = None
    if i > 0 and prefix.document_ids[i - 1] == prefix.document_ids[i]:
        prev = prefix.token_strings[i - 1].strip().lower()
    if cur in OBJECT_PRONOUNS:
        if prev in TALK_VERBS:
            return carry, 4.0
        if prev in CAUSE_WORDS:
            return carry, 0.0
        return carry, 1.0
    if prev in OBJECT_PRONOUNS and cur in PARTICLES:
        return carry, 3.0
    if cur in PARTICLES:
        return carry, 0.2
    return carry, 0.0

"""Layer 15 MLP down_proj, component 3230: a discourse-connective detector.

What it does: this component reads the MLP's hidden state and writes a small
signed amount into the residual stream. Its activation is mostly near zero, but
it goes strongly negative on words that open an explanation or a consequence
("In fact", "Indeed", "That is why", "for this reason", "therefore", "hence"),
and on the 'that' of a "so (much) ... that" result clause and the subject right
after it. It goes mildly positive on contrast and condition words ("but",
"instead", "unless", "or", "however", "if", "when").

The program is a hand-built rule over the last few words of the same document,
with values fitted by least squares on training rows. It is a readable
approximation: it explains only a small share of the component's variance.
"""

CONSEQUENCE = {"indeed", "fact", "why", "reason", "therefore", "hence", "accordingly", "consequently"}
ELABORATION = {"thus", "example", "instance", "including", "even", "enough"}
SO_WORDS = {"so", "such", "much"}
CONTRAST = {"but", "instead", "unless", "or", "however", "rather"}
CONDITION = {"if", "when"}
PRONOUNS = {"he", "she", "they", "it", "i", "we", "you"}
PUNCT = {",", ".", "，"}

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    w = prefix.token_strings[t].strip().lower()
    # the up to three words before this one, within the same document
    recent = []
    for back in range(1, 4):
        if t - back < 0 or docs[t - back] != docs[t]:
            break
        recent.append(prefix.token_strings[t - back].strip().lower())
    prev = recent[0] if recent else ""
    value = 0.04  # the component's average activation
    if w in CONSEQUENCE:
        value = -1.4
    elif w in ELABORATION:
        value = -0.7
    elif w in SO_WORDS:
        value = -0.5
    elif w in CONTRAST:
        value = 0.36
    elif w in CONDITION:
        value = 0.2
    if w == "that" and any(x in SO_WORDS for x in recent):
        value = -1.0
    if w in PUNCT and prev in CONSEQUENCE | ELABORATION:
        value = -0.45
    if w in PRONOUNS and prev in SO_WORDS:
        value = -0.9
    return carry, value

"""Component layers.15.mlp.down_proj:3232, read as a rule on the words.

This component is one MLP hidden unit of layer 15 (its input direction is almost
entirely that unit). It is quiet on most text and responds to three things:

1. The opening of an assistant's reply. The newline just after <think> or </think>
   is strongest; the first few words of the reply are next; the effect fades
   over the first ~10 tokens of the turn.
2. Reflective and reaction words. "Wait", "Hmm", "Sorry", "Perfect", "Excellent",
   "Hello" are strong. "however", "actually", "seems", "but", "confusing",
   "unclear" and similar are weaker. Both are amplified at the start of an
   assistant reply and are slightly stronger inside assistant turns.
3. The chat role names "user" and "assistant" outside an assistant turn are
   slightly negative.

Everything else predicts 0. The reply position is tracked from the chat template
(<|im_start|>role ... <|im_end|>), and state resets at each new document.
"""

READS = ()

# Words that signal self-correction or a reaction (strong) and weaker discourse
# or doubt words.
STRONG = {"wait", "hmm", "perfect", "excellent", "sorry", "hi", "hello"}
WEAK = {"thanks", "oh", "great", "good", "but", "however", "actually", "seems",
        "sounds", "okay", "confusing", "confused", "unclear", "ambiguous",
        "inconsistent", "incorrect", "unfortunately", "interesting"}
ROLE_NAMES = {"user", "assistant"}
PUNCT = {",", ".", "?", "!"}
EARLY = 10  # tokens into an assistant turn that count as its opening


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "role": None, "off": 0, "pending": False}
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""

    # Track which chat turn we are in: the role name follows <|im_start|>.
    if s == "<|im_start|>":
        carry["pending"] = True
    elif carry["pending"]:
        carry["pending"] = False
        carry["role"] = w if w in ROLE_NAMES else None
        carry["off"] = 0
    elif s == "<|im_end|>":
        carry["role"] = None

    asst = carry["role"] == "assistant"
    early = False
    value = 0.0
    if asst:
        carry["off"] += 1
        early = carry["off"] <= EARLY
        if early:
            value += 1.0
        elif carry["off"] <= 40:
            value += 0.25
        if w in PUNCT:
            value += 0.5
    elif w in ROLE_NAMES:
        value -= 0.6

    if w in STRONG:
        value += 3.5
        if early:
            value += 5.0
    elif w in WEAK:
        value += 0.9
        if asst:
            value += 1.8
        if early:
            value += 3.5

    if s in ("\n", "\n\n") and prev in ("<think>", "</think>"):
        value += 6.5
    return carry, value

"""Component 3244 of layers.15.mlp.down_proj in Qwen3-1.7B, as a word-level rule.

In plain terms: the component goes negative inside words that are verbs,
adjectives or event/process words, most strongly on the later pieces of a
split word ("-ized", "-ing", "-ed", "-able", "-less", "-ation"), and on event
words such as "birth", "death", "educated", "arrested". It is near zero on
ordinary nouns and on words it does not know, slightly positive on adverbs,
spaces and punctuation, and negative on CJK characters. It does not look at
the next token: it reads only the word being built up so far.

Part of speech and word class come from WordNet, applied to the word assembled
from the current token and any earlier pieces of the same word. The levels are
rounded means measured on training text, scaled by SHRINK.
"""

import regex
import wordnet

READS = ()

# Predictions are scaled by SHRINK. The best straight-line fit to the activation is about 0.7x these
# levels; a smaller scale moves the model's next-token loss less but fits the activation less well.
SHRINK = 0.5

EVENT = {
    "noun.event", "noun.process", "noun.act", "noun.feeling", "noun.state",
    "noun.phenomenon", "verb.body", "verb.emotion", "verb.change", "verb.motion",
}


def word_level(word, piece):
    """Level for a Latin-letter word, given its WordNet classes and parts of speech."""
    pos = wordnet.parts_of_speech(word)
    if set(wordnet.categories(word)) & EVENT:
        level = -1.0
    elif "verb" in pos or "adjective" in pos:
        level = -0.8
    elif "adverb" in pos:
        return 0.3
    elif "noun" in pos:
        return 0.0
    else:
        return -0.3 if piece else 0.05
    return -2.0 if piece else level


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return "", 0.0  # a document's first token: activation is about 0
    tok = tokens[-1]
    if regex.fullmatch(r"[A-Za-z]+", tok.strip()):
        piece = bool(carry) and not tok.startswith(" ")
        word = (carry if piece else "") + tok.strip().lower()
        return word, SHRINK * word_level(word, piece)
    if regex.fullmatch(r"\p{Han}+", tok.strip()):
        before = tokens[-2].strip()
        return "", SHRINK * (-0.9 if regex.fullmatch(r"\p{Han}+", before) else -0.6)
    if regex.fullmatch(r"[\p{Hiragana}\p{Katakana}]+", tok.strip()):
        return "", SHRINK * -0.5
    if not regex.search(r"[\p{L}\p{N}]", tok):
        return "", SHRINK * 0.2  # spaces and punctuation
    if tok.strip().isdigit():
        return "", SHRINK * 0.1
    return "", SHRINK * -0.1

"""Conclusion connectives: the words that draw a result out of what came before.

Component p-82af68dd@100000/layers.15.mlp.down_proj:3250 goes strongly negative on the word
that opens a conclusion: "Thus", "Therefore", "Hence", "So" (as in "So, x = 2"),
"Consequently", "因此", "所以", "поэтому" and similar. Its size is about -3 to -4 at those
words, and smaller for "so" used as an intensifier or in "do so" / "is so". It is also
negative, about -1, on the comma or full stop that closes a conclusion, and weakly negative
on words that spell out what a claim implies ("means", "meaning", "implies", "i.e.").
Other text is near zero, with a slight dip on punctuation. It reads only the current token
and the one before it, in the same document.
"""

READS = ()

# Words that open a conclusion, with their typical activation.
CONCLUSION = {
    "hence": -4.0, "therefore": -3.7, "thus": -3.5, "so": -2.8,
    "consequently": -3.0, "thereby": -1.7, "accordingly": -1.5, "ergo": -2.0,
    "因此": -3.7, "所以": -3.4, "故": -1.4, "ので": -2.3, "поэтому": -3.5,
    "daher": -2.4, "donc": -2.1,
}
# Words that spell out what a claim implies: weakly negative.
IMPLIES = {"means": -0.5, "meaning": -0.6, "implies": -0.6, "implying": -0.9,
           "suggesting": -1.2, "indicating": -0.9, "why": -0.5, ".e": -1.0}
# Words after which a comma or full stop closes a conclusion phrase ("As a result,").
PHRASE_END = {"result", "reason", "words", "such"}
# "so" after these is an intensifier or "do so", not a conclusion.
NOT_CONCLUSION_BEFORE_SO = {"do", "is", "was", "are", "not", "be", "doing", "much", "far"}
PUNCTUATION = {",", ".", ";", ":", "\n", ".\n", ".\n\n", ",\n\n"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in CONCLUSION:
        if word == "so" and before in NOT_CONCLUSION_BEFORE_SO:
            return carry, -0.3
        return carry, CONCLUSION[word]
    if word in IMPLIES:
        return carry, IMPLIES[word]
    if word in PUNCTUATION and (before in CONCLUSION or before in PHRASE_END):
        return carry, -1.2
    if word in PUNCTUATION:
        return carry, -0.1
    return carry, 0.0

"""Layer 15 MLP down-projection, component 3257 (a weak, diffuse feature).

What it does: this component reads the MLP hidden state and writes a small, mostly
context-driven amount into the residual stream. Its activation is near zero on most
tokens and has a heavy tail. The clearest part of the tail is the comma that closes an
introductory phrase at the start of a sentence:

  * "If you ...,", "Depending on ...,", "Once ...,", "When ...," (a conditional or
    circumstance clause, with the main clause still to come): clearly positive;
  * "In some cases,", "In certain circumstances,", "For a ...," (other adverbial
    openers): mildly positive;
  * "Therefore,", "In addition,", "In fact,", "However," (discourse connectives): mildly negative;
  * every other token: about zero.

Modal verbs and hedging adverbs (may, can, might, could, even, then, sometimes, often)
carry a weak positive mean, and so does "cases" (as in "in some cases").

The numbers are rounded means of the activation in each class, measured on about
4,000 training rows (2M positions). The program is therefore a weak predictor: on
the eval rows it explains about 0.3% of the activation variance (correlation 0.06),
and switching its predictions in leaves the next-token distribution essentially
unchanged (kl_fraction 0.994). Most of the variance sits in diffuse positions that
no token identity, n-gram or simple sentence rule captures; a lookup on the current
token alone explains only about 1%.
"""

READS = ()

COMMAS = {",", "，", "、"}
CONDITIONAL = {"If", "When", "Once", "Unless", "Whether", "Depending", "Because", "Since",
               "Although", "Given", "Wenn", "Si", "Falls", "Lorsque", "Quand"}
ADVERBIAL = {"In", "For", "At", "Under", "During", "With", "On", "After", "Before", "Within"}
CONNECTIVE = {"Therefore", "Thus", "However", "Instead", "Also", "Moreover", "Furthermore",
              "Finally", "Overall", "Hence", "Indeed", "Additionally", "Consequently", "Still",
              "Yet", "So", "Then", "Unfortunately", "Of"}
CONNECTIVE_SECOND = {"addition", "fact", "conclusion", "summary", "contrast", "short",
                     "general", "particular", "other", "turn", "comparison", "sum", "order"}
HEDGES = {"may": 0.45, "can": 0.25, "might": 0.3, "could": 0.2, "even": 0.55,
          "then": 0.3, "sometimes": 2.0, "often": 0.35, "cases": 1.1}
SENTENCE_END = (".", "!", "?", "。", "！", "？")
MAX_LOOKBACK = 40


def _ends_sentence(text):
    return "\n" in text or text.strip().endswith(SENTENCE_END)


def step(carry, prefix, upstream):
    t = prefix.position
    strings = prefix.token_strings
    docs = prefix.document_ids
    tok = strings[t].strip()
    if t == 0:
        return carry, 0.0
    if tok in HEDGES:
        return carry, HEDGES[tok]
    if tok not in COMMAS:
        return carry, 0.0
    # Walk back to the start of this sentence, within this document.
    j = t - 1
    while j >= 0 and docs[j] == docs[t] and t - j < MAX_LOOKBACK:
        if strings[j].strip() in COMMAS:
            return carry, 0.0  # not the sentence's first comma
        if _ends_sentence(strings[j]):
            break
        j -= 1
    words = [strings[k].strip() for k in range(j + 1, t) if strings[k].strip()]
    if not words:
        return carry, 0.0
    first = words[0]
    second = words[1].lower() if len(words) > 1 else ""
    if first in CONDITIONAL:
        return carry, 0.65
    if first in ADVERBIAL and second not in CONNECTIVE_SECOND:
        return carry, 0.25
    if first in CONNECTIVE:
        return carry, -0.15
    return carry, 0.0
